-- Rückbau 201: Funktionen ally_sicherung_* und die Tabellen ally_sicherung_ziele, ally_sicherung_server, ally_sicherung_laeufe entfernen. Vorher ALLY 20 und ALLY 23
-- zurücksetzen und das Sicherungsprogramm auf dem Server abschalten (docs/sicherung.md, Abschnitt Rückbau). Keine Daten gehen verloren: der Inhalt der drei Tabellen
-- kommt vorher in die Sicherungstabellen ally_sicherung_ziele_rb201, ally_sicherung_server_rb201, ally_sicherung_laeufe_rb201 (das Kennwort bleibt verschlüsselt).
-- Nur auf dem Stand von 201. Nur als Ganzes in einer Transaktion.
DO $m$
BEGIN
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind = 'r' AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_sicherung_laeufe', 'ally_sicherung_server', 'ally_sicherung_ziele'])) = 0 AND (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" LIKE 'ally\_sicherung\_%') IS NULL THEN RAISE EXCEPTION 'Rückbau 201: schon zurückgebaut, nichts geändert'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind = 'r' AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_sicherung_laeufe', 'ally_sicherung_server', 'ally_sicherung_ziele'])) <> 3 OR (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_sicherung_laeufe', 'ally_sicherung_server', 'ally_sicherung_ziele'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) IS DISTINCT FROM '4d61775f5a8485822c7ff5c30815f9a1' THEN RAISE EXCEPTION 'Rückbau 201: Tabellen nicht im Stand von 201, nichts geändert'; END IF;
  IF (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" LIKE 'ally\_sicherung\_%') IS DISTINCT FROM 'a5836893209fb77c3dbdca628a473ac1' THEN RAISE EXCEPTION 'Rückbau 201: Funktionen nicht im Stand von 201, nichts geändert'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_sicherung_laeufe_rb201', 'ally_sicherung_server_rb201', 'ally_sicherung_ziele_rb201'])) <> 0 THEN RAISE EXCEPTION 'Rückbau 201: Sicherungstabellen _rb201 schon vorhanden, nichts geändert'; END IF;
  PERFORM set_config('m201.inhalt', (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (SELECT '0|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM public.ally_sicherung_laeufe x UNION ALL SELECT '1|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM public.ally_sicherung_server x UNION ALL SELECT '2|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM public.ally_sicherung_ziele x) y), true);
END $m$;
CREATE TABLE public.ally_sicherung_laeufe_rb201 AS SELECT * FROM public.ally_sicherung_laeufe;
CREATE TABLE public.ally_sicherung_server_rb201 AS SELECT * FROM public.ally_sicherung_server;
CREATE TABLE public.ally_sicherung_ziele_rb201 AS SELECT * FROM public.ally_sicherung_ziele;
DO $m$
BEGIN
  IF current_setting('m201.inhalt') IS DISTINCT FROM (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (SELECT '0|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM public.ally_sicherung_laeufe_rb201 x UNION ALL SELECT '1|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM public.ally_sicherung_server_rb201 x UNION ALL SELECT '2|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM public.ally_sicherung_ziele_rb201 x) y) THEN RAISE EXCEPTION 'Rückbau 201: Sicherung der Tabellen unvollständig, nichts geändert'; END IF;
END $m$;
DROP FUNCTION public.ally_sicherung_host_ende(p_lauf bigint, p_ergebnis text, p_groesse bigint, p_belegt bigint, p_staende integer, p_meldung text);
DROP FUNCTION public.ally_sicherung_host_hostschluessel(p_lauf bigint, p_zeile text, p_fp text);
DROP FUNCTION public.ally_sicherung_host_kennwort(p_lauf bigint);
DROP FUNCTION public.ally_sicherung_kunde_inhalt(p_lauf bigint);
DROP FUNCTION public.ally_sicherung_host_ziel(p_lauf bigint);
DROP FUNCTION public.ally_sicherung_host_plan(p_meldung jsonb);
DROP FUNCTION public.ally_sicherung_ui_aktion(p_token text, p_csrf text, p_aktion text, p_daten jsonb, p_zustand jsonb, p_geheim jsonb);
DROP FUNCTION public.ally_sicherung_ui(p_token text);
DROP FUNCTION public.ally_sicherung_ziel_ui(p_art text);
DROP FUNCTION public.ally_sicherung_termin(p_ziel ally_sicherung_ziele, p_zeit timestamp with time zone, p_naechster boolean);
DROP FUNCTION public.ally_sicherung_zeit(p_zeit timestamp with time zone);
DROP FUNCTION public.ally_sicherung_ziel(p_art text);
DROP FUNCTION public.ally_sicherung_standard(p_art text);
DROP TABLE public.ally_sicherung_laeufe;
DROP TABLE public.ally_sicherung_server;
DROP TABLE public.ally_sicherung_ziele;
DO $m$
BEGIN
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind = 'r' AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_sicherung_laeufe', 'ally_sicherung_server', 'ally_sicherung_ziele'])) <> 0 OR (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" LIKE 'ally\_sicherung\_%') IS NOT NULL OR (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_sicherung_laeufe', 'ally_sicherung_server', 'ally_sicherung_ziele'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) IS NOT NULL THEN RAISE EXCEPTION 'Rückbau 201: nicht vollständig entfernt'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_sicherung_laeufe_rb201', 'ally_sicherung_server_rb201', 'ally_sicherung_ziele_rb201'])) <> 3 THEN RAISE EXCEPTION 'Rückbau 201: Sicherungstabellen fehlen'; END IF;
END $m$;
